package com.estoqueinteligente.report;
import com.estoqueinteligente.product.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class SmartSuggestionService{private final ProductService products;public SmartSuggestionService(ProductService p){products=p;}public List<SmartSuggestionResponse> getSuggestions(){List<SmartSuggestionResponse> out=new ArrayList<>();for(ProductResponse p:products.findAll()){if(p.getStatus()==ProductStatus.PENDENTE_CONTAGEM)out.add(s(p,SuggestionType.PENDENTE_CONTAGEM,SuggestionPriority.MEDIA,"O item "+p.getName()+" está sem contagem atual. Sugestão: realizar conferência do almoxarifado."));if(p.getStatus()==ProductStatus.SALDO_NEGATIVO)out.add(s(p,SuggestionType.SALDO_NEGATIVO,SuggestionPriority.ALTA,"O item "+p.getName()+" está com saldo negativo. Sugestão: repor "+Math.abs(p.getBalance())+" "+(p.getUnitOfMeasure()==null?"unidade(s)":p.getUnitOfMeasure())+"."));if(p.getStatus()==ProductStatus.NECESSIDADE_REPOSICAO)out.add(s(p,SuggestionType.NECESSIDADE_REPOSICAO,SuggestionPriority.ALTA,"O item "+p.getName()+" precisa de reposição antes do próximo uso."));}out.sort(Comparator.comparing(SmartSuggestionResponse::getPriority));return out;}private SmartSuggestionResponse s(ProductResponse p,SuggestionType t,SuggestionPriority priority,String m){return new SmartSuggestionResponse(t,priority,m,p.getId(),p.getName());}}
